export type RequestInput={freight_arrivals:number;service_boats:number;channel_crews:number;fog_alert:boolean};
export const harborSignalIndex=(f:number,s:number,c:number,g:boolean)=>{
  const vesselCount=f+s;
  const baseBeacons=c*6;
  const fogBeacons=g?c*2:0;
  const activeBeacons=Math.max(baseBeacons-fogBeacons,0);
  const unsignaledVessels=Math.max(vesselCount-activeBeacons,0);
  const crewLoad=Math.min(vesselCount,activeBeacons)*3;
  return unsignaledVessels*11+crewLoad;
};
export const handle=(v:RequestInput)=>{const vessels=v.freight_arrivals+v.service_boats,base=v.channel_crews*6,fog=v.fog_alert?v.channel_crews*2:0,active=Math.max(base-fog,0),unsignaled=Math.max(vessels-active,0),crew=Math.min(vessels,active)*3;return {vessel_count:vessels,base_beacons:base,fog_beacons:fog,active_beacons:active,unsignaled_vessels:unsignaled,crew_load:crew,signal_index:harborSignalIndex(v.freight_arrivals,v.service_boats,v.channel_crews,v.fog_alert),harbor_state:unsignaled===0?"clear":v.fog_alert?"fog_hold":"congested"};};
export async function loadParley(){return {harbor_signal_index:(f:number,s:number,c:number,g:boolean)=>BigInt(harborSignalIndex(f,s,c,g))};}

