const museumRotationIndex = (permanentPieces, borrowedPieces, roomCount, lateOpening) => {
  const viewingMinutes = permanentPieces * 9 + borrowedPieces * 14;
  const lateMinutes = lateOpening ? roomCount * 20 : 0;
  const programMinutes = viewingMinutes + lateMinutes;
  const tourBlocks = Math.ceil(programMinutes / 60);
  const labelPoints = borrowedPieces * 5 + roomCount * 4;
  return programMinutes + tourBlocks * 7 + labelPoints;
};
export async function loadParley() { return { museum_rotation_index: museumRotationIndex }; }

