const museumRotationIndex = (permanentPieces, borrowedPieces, roomCount, lateOpening) => {
  const permanent = BigInt(permanentPieces);
  const borrowed = BigInt(borrowedPieces);
  const rooms = BigInt(roomCount);
  const viewing = permanent * 9n + borrowed * 14n;
  const late = lateOpening ? rooms * 20n : 0n;
  const program = viewing + late;
  const tourBlocks = (program + 59n) / 60n;
  const labelPoints = borrowed * 5n + rooms * 4n;
  return program + tourBlocks * 7n + labelPoints;
};

