export const rooftopUtilityDraw=(s:number,h:number,b:number,r:boolean)=>{const g=Math.max(h-s,0),p=r?Math.min(b,4):0,c=Math.max(b-p,0),d=Math.min(g,c);return Math.max(g-d,0);};
export const handle=(v:RequestInput)=>{const gap=Math.max(v.household_units-v.solar_units,0),protectedUnits=v.reserve_enabled?Math.min(v.stored_units,4):0,ceiling=Math.max(v.stored_units-protectedUnits,0),delivery=Math.min(gap,ceiling),utility=rooftopUtilityDraw(v.solar_units,v.household_units,v.stored_units,v.reserve_enabled),balance=Math.max(v.stored_units-delivery,0);return {energy_gap:gap,protected_units:protectedUnits,discharge_ceiling:ceiling,battery_delivery:delivery,utility_units:utility,storage_balance:balance,reserve_margin:Math.max(balance-protectedUnits,0),supply_state:gap===0?"self_powered":utility===0?"battery":"grid"};};
export async function loadParley(){return {rooftop_utility_draw:(s:number,h:number,b:number,r:boolean)=>BigInt(rooftopUtilityDraw(s,h,b,r))};}

