export type RequestInput={solar_units:number;household_units:number;stored_units:number;reserve_enabled:boolean};
const calculate=(s:number,h:number,b:number,r:boolean)=>{
  const energyGap=Math.max(h-s,0);
  const protectedUnits=r?Math.min(b,4):0;
  const dischargeCeiling=Math.max(b-protectedUnits,0);
  const batteryDelivery=Math.min(energyGap,dischargeCeiling);
  const utilityUnits=Math.max(energyGap-batteryDelivery,0);
  const storageBalance=Math.max(b-batteryDelivery,0);
  return {energyGap,protectedUnits,dischargeCeiling,batteryDelivery,utilityUnits,storageBalance};
};
export const rooftopUtilityDraw=(s:number,h:number,b:number,r:boolean)=>calculate(s,h,b,r).utilityUnits;
export const handle=(v:RequestInput)=>{const result=calculate(v.solar_units,v.household_units,v.stored_units,v.reserve_enabled);return {energy_gap:result.energyGap,protected_units:result.protectedUnits,discharge_ceiling:result.dischargeCeiling,battery_delivery:result.batteryDelivery,utility_units:result.utilityUnits,storage_balance:result.storageBalance,reserve_margin:Math.max(result.storageBalance-result.protectedUnits,0),supply_state:result.energyGap===0?"self_powered":result.utilityUnits===0?"battery":"grid"};};
export async function loadParley(){return {rooftop_utility_draw:(s:number,h:number,b:number,r:boolean)=>BigInt(rooftopUtilityDraw(s,h,b,r))};}

