use serde::{Deserialize, Serialize};

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RequestInput {
    pub permanent_pieces: i64,
    pub borrowed_pieces: i64,
    pub room_count: i64,
    pub late_opening: bool,
}

impl RequestInput {
    pub fn valid(&self) -> bool {
        self.permanent_pieces >= 0 && self.borrowed_pieces >= 0 && self.room_count >= 0
    }
}

#[derive(Serialize)]
pub struct ResponseOutput {
    pub collection_size: i64,
    pub viewing_minutes: i64,
    pub late_minutes: i64,
    pub program_minutes: i64,
    pub tour_blocks: i64,
    pub label_points: i64,
    pub rotation_index: i64,
    pub exhibit_mode: String,
}

pub fn museum_rotation_index(p: i64, b: i64, r: i64, l: bool) -> i64 {
    let viewing = p * 9 + b * 14;
    let late = if l { r * 20 } else { 0 };
    let program = viewing + late;
    let tour_blocks = if program == 0 { 0 } else { (program + 59) / 60 };
    let label_points = b * 5 + r * 4;
    program + tour_blocks * 7 + label_points
}

pub fn handle(v: RequestInput) -> ResponseOutput {
    let viewing = v.permanent_pieces * 9 + v.borrowed_pieces * 14;
    let late = if v.late_opening { v.room_count * 20 } else { 0 };
    let program = viewing + late;
    ResponseOutput {
        collection_size: v.permanent_pieces + v.borrowed_pieces,
        viewing_minutes: viewing,
        late_minutes: late,
        program_minutes: program,
        tour_blocks: if program == 0 { 0 } else { (program + 59) / 60 },
        label_points: v.borrowed_pieces * 5 + v.room_count * 4,
        rotation_index: museum_rotation_index(
            v.permanent_pieces,
            v.borrowed_pieces,
            v.room_count,
            v.late_opening,
        ),
        exhibit_mode: if v.borrowed_pieces > v.permanent_pieces {
            "loan_focus"
        } else if v.borrowed_pieces > 0 {
            "blended"
        } else {
            "permanent"
        }
        .into(),
    }
}

#[unsafe(no_mangle)]
pub extern "C" fn parley_museum_rotation_index(a: i64, b: i64, c: i64, d: i32) -> i64 {
    museum_rotation_index(a, b, c, d != 0)
}

