export type RequestInput={solar_units:number;household_units:number;stored_units:number;reserve_enabled:boolean};
export const rooftopUtilityDraw=(s:number,h:number,b:number,r:boolean)=>{const g=Math.max(h-s,0),p=r?Math.min(b,4):0;return Math.max(g-Math.min(g,b),0);};
