#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RequestInput {
    pub solar_units: i64,
    pub household_units: i64,
    pub stored_units: i64,
    pub reserve_enabled: bool,
}

impl RequestInput {
    pub fn valid(&self) -> bool {
        self.solar_units >= 0 && self.household_units >= 0 && self.stored_units >= 0
    }
}

#[derive(Serialize)]
pub struct ResponseOutput {
    pub energy_gap: i64,
    pub protected_units: i64,
    pub discharge_ceiling: i64,
    pub battery_delivery: i64,
    pub utility_units: i64,
    pub storage_balance: i64,
    pub reserve_margin: i64,
    pub supply_state: String,
}

fn calculate(solar_units: i64, household_units: i64, stored_units: i64, reserve_enabled: bool) -> ResponseOutput {
    let energy_gap = household_units.saturating_sub(solar_units).max(0);
    let protected_units = if reserve_enabled { stored_units.min(4).max(0) } else { 0 };
    let discharge_ceiling = stored_units.saturating_sub(protected_units).max(0);
    let battery_delivery = energy_gap.min(discharge_ceiling);
    let utility_units = energy_gap.saturating_sub(battery_delivery).max(0);
    let storage_balance = stored_units.saturating_sub(battery_delivery).max(0);
    let reserve_margin = storage_balance.saturating_sub(protected_units).max(0);
    let supply_state = if energy_gap == 0 {
        "self_powered"
    } else if utility_units == 0 {
        "battery"
    } else {
        "grid"
    }.into();

    ResponseOutput { energy_gap, protected_units, discharge_ceiling, battery_delivery, utility_units, storage_balance, reserve_margin, supply_state }
}

