export type RequestInput = {
  requested_crates: number;
  damaged_crates: number;
  truck_count: number;
  lift_assist: boolean;
};

const loadingSlots = (truckCount: number, liftAssist: boolean) =>
  truckCount * 16 + (liftAssist ? truckCount * 2 : 0);

export const bookmobileDeferredCrates = (
  requestedCrates: number,
  damagedCrates: number,
  truckCount: number,
  liftAssist: boolean,
) =>
  Math.max(
    Math.max(requestedCrates - damagedCrates, 0) -
      loadingSlots(truckCount, liftAssist),
    0,
  );

export const handle = (value: RequestInput) => {
  const soundCrates = Math.max(
    value.requested_crates - value.damaged_crates,
    0,
  );
  const deckSlots = value.truck_count * 16;
  const liftSlots = value.lift_assist ? value.truck_count * 2 : 0;
  const slots = deckSlots + liftSlots;
  const deferredCrates = bookmobileDeferredCrates(
    value.requested_crates,
    value.damaged_crates,
    value.truck_count,
    value.lift_assist,
  );
  const boardedCrates = Math.min(soundCrates, slots);

  return {
    sound_crates: soundCrates,
    deck_slots: deckSlots,
    lift_slots: liftSlots,
    loading_slots: slots,
    deferred_crates: deferredCrates,
    boarded_crates: boardedCrates,
    empty_slots: Math.max(slots - boardedCrates, 0),
    loading_state: deferredCrates
      ? "deferred"
      : boardedCrates
        ? "loaded"
        : "idle",
  };
};

export async function loadParley() {
  return { bookmobile_deferred_crates: bookmobileDeferredCrates };
}

