use serde::{Deserialize, Serialize};

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RequestInput {
    pub freight_arrivals: i64,
    pub service_boats: i64,
    pub channel_crews: i64,
    pub fog_alert: bool,
}

impl RequestInput {
    pub fn valid(&self) -> bool {
        self.freight_arrivals >= 0 && self.service_boats >= 0 && self.channel_crews >= 0
    }
}

#[derive(Serialize)]
pub struct ResponseOutput {
    pub vessel_count: i64,
    pub base_beacons: i64,
    pub fog_beacons: i64,
    pub active_beacons: i64,
    pub unsignaled_vessels: i64,
    pub crew_load: i64,
    pub signal_index: i64,
    pub harbor_state: String,
}

pub fn harbor_signal_index(freight_arrivals: i64, service_boats: i64, channel_crews: i64, fog_alert: bool) -> i64 {
    let vessel_count = freight_arrivals + service_boats;
    let base_beacons = channel_crews * 6;
    let fog_beacons = if fog_alert { channel_crews * 2 } else { 0 };
    let active_beacons = (base_beacons - fog_beacons).max(0);
    let unsignaled_vessels = (vessel_count - active_beacons).max(0);
    let crew_load = vessel_count.min(active_beacons) * 3;

    unsignaled_vessels * 11 + crew_load
}

pub fn handle(v: RequestInput) -> ResponseOutput {
    let vessels = v.freight_arrivals + v.service_boats;
    let base = v.channel_crews * 6;
    let fog = if v.fog_alert { v.channel_crews * 2 } else { 0 };
    let active = (base - fog).max(0);
    let unsignaled = (vessels - active).max(0);

    ResponseOutput {
        vessel_count: vessels,
        base_beacons: base,
        fog_beacons: fog,
        active_beacons: active,
        unsignaled_vessels: unsignaled,
        crew_load: vessels.min(active) * 3,
        signal_index: harbor_signal_index(
            v.freight_arrivals,
            v.service_boats,
            v.channel_crews,
            v.fog_alert,
        ),
        harbor_state: if unsignaled == 0 {
            "clear"
        } else if v.fog_alert {
            "fog_hold"
        } else {
            "congested"
        }
        .into(),
    }
}

#[unsafe(no_mangle)]
pub extern "C" fn parley_harbor_signal_index(a: i64, b: i64, c: i64, d: i32) -> i64 {
    harbor_signal_index(a, b, c, d != 0)
}

