use serde::{Deserialize, Serialize};

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RequestInput {
    pub permanent_pieces: i64,
    pub borrowed_pieces: i64,
    pub room_count: i64,
    pub late_opening: bool,
}

impl RequestInput {
    pub fn valid(&self) -> bool {
        self.permanent_pieces >= 0 && self.borrowed_pieces >= 0 && self.room_count >= 0
    }
}

#[derive(Serialize)]
pub struct ResponseOutput {
    pub collection_size: i64,
    pub viewing_minutes: i64,
    pub late_minutes: i64,
    pub program_minutes: i64,
    pub tour_blocks: i64,
    pub label_points: i64,
    pub rotation_index: i64,
    pub exhibit_mode: String,
}

pub fn museum_rotation_index(
    permanent_pieces: i64,
    borrowed_pieces: i64,
    room_count: i64,
    late_opening: bool,
) -> i64 {
    let viewing_minutes = permanent_pieces * 9 + borrowed_pieces * 14;
    let late_minutes = if late_opening { room_count * 20 } else { 0 };
    let program_minutes = viewing_minutes + late_minutes;
    let tour_blocks = (program_minutes + 59) / 60;
    let label_points = borrowed_pieces * 5 + room_count * 4;

    program_minutes + tour_blocks * 7 + label_points
}

pub fn handle(value: RequestInput) -> ResponseOutput {
    let viewing_minutes = value.permanent_pieces * 9 + value.borrowed_pieces * 14;
    let late_minutes = if value.late_opening {
        value.room_count * 20
    } else {
        0
    };
    let program_minutes = viewing_minutes + late_minutes;
    let tour_blocks = (program_minutes + 59) / 60;
    let label_points = value.borrowed_pieces * 5 + value.room_count * 4;
    let rotation_index = program_minutes + tour_blocks * 7 + label_points;
    let exhibit_mode = if value.borrowed_pieces > value.permanent_pieces {
        "loan_focus"
    } else if value.borrowed_pieces > 0 {
        "blended"
    } else {
        "permanent"
    };

    ResponseOutput {
        collection_size: value.permanent_pieces + value.borrowed_pieces,
        viewing_minutes,
        late_minutes,
        program_minutes,
        tour_blocks,
        label_points,
        rotation_index,
        exhibit_mode: exhibit_mode.into(),
    }
}

#[unsafe(no_mangle)]
pub extern "C" fn parley_museum_rotation_index(a: i64, b: i64, c: i64, d: i32) -> i64 {
    museum_rotation_index(a, b, c, d != 0)
}

