function harborSignalIndex(freightArrivals, serviceBoats, channelCrews, fogAlert) {
  const vesselCount = freightArrivals + serviceBoats;
  const baseBeacons = channelCrews * 6;
  const fogBeacons = fogAlert ? channelCrews * 2 : 0;
  const activeBeacons = Math.max(baseBeacons - fogBeacons, 0);
  const unsignaledVessels = Math.max(vesselCount - activeBeacons, 0);
  const crewLoad = Math.min(vesselCount, activeBeacons) * 3;
  return unsignaledVessels * 11 + crewLoad;
}

export async function loadParley() {
  return { harbor_signal_index: harborSignalIndex };
}

