use serde::{Deserialize, Serialize};

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RequestInput {
    pub requested_crates: i64,
    pub damaged_crates: i64,
    pub truck_count: i64,
    pub lift_assist: bool,
}

impl RequestInput {
    pub fn valid(&self) -> bool {
        self.requested_crates >= 0 && self.damaged_crates >= 0 && self.truck_count >= 0
    }
}

#[derive(Serialize)]
pub struct ResponseOutput {
    pub sound_crates: i64,
    pub deck_slots: i64,
    pub lift_slots: i64,
    pub loading_slots: i64,
    pub deferred_crates: i64,
    pub boarded_crates: i64,
    pub empty_slots: i64,
    pub loading_state: String,
}

fn loading_slots(truck_count: i64, lift_assist: bool) -> (i64, i64, i64) {
    let deck_slots = truck_count * 16;
