    let vessel_count = v.freight_arrivals + v.service_boats;
    let base_beacons = v.channel_crews * 6;
    let fog_beacons = if v.fog_alert { v.channel_crews * 2 } else { 0 };
    let active_beacons = (base_beacons - fog_beacons).max(0);
    let unsignaled_vessels = (vessel_count - active_beacons).max(0);
    let crew_load = vessel_count.min(active_beacons) * 3;

    ResponseOutput {
        vessel_count,
        base_beacons,
        fog_beacons,
        active_beacons,
        unsignaled_vessels,
        crew_load,
        signal_index: unsignaled_vessels * 11 + crew_load,
        harbor_state: if unsignaled_vessels == 0 {
            "clear".into()
        } else if v.fog_alert {
            "fog_hold".into()
        } else {
            "congested".into()
        },
    }
}

