export type RequestInput={solar_units:number;household_units:number;stored_units:number;reserve_enabled:boolean};
export const rooftopUtilityDraw=(s:number,h:number,b:number,r:boolean)=>{
  const energyGap=Math.max(h-s,0);
  const protectedUnits=r?Math.min(b,4):0;
  const dischargeCeiling=Math.max(b-protectedUnits,0);
  const batteryDelivery=Math.min(energyGap,dischargeCeiling);
  return Math.max(energyGap-batteryDelivery,0);
};
export const handle=(v:RequestInput)=>{const gap=Math.max(v.household_units-v.solar_units,0),protectedUnits=v.reserve_enabled?Math.min(v.stored_units,4):0,ceiling=Math.max(v.stored_units-protectedUnits,0),delivery=Math.min(gap,ceiling),utility=Math.max(gap-delivery,0),balance=Math.max(v.stored_units-delivery,0);return {energy_gap:gap,protected_units:protectedUnits,discharge_ceiling:ceiling,battery_delivery:delivery,utility_units:utility,storage_balance:balance,reserve_margin:Math.max(balance-protectedUnits,0),supply_state:gap===0?"self_powered":utility===0?"battery":"grid"};};
export async function loadParley(){return {rooftop_utility_draw:(s:number,h:number,b:number,r:boolean)=>BigInt(rooftopUtilityDraw(s,h,b,r))};}

